    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 74700, discount: 0, total: 74700 });
});

test('invoiceTotals works with a real invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const expected = 8 * 8500 + 5 * 9500;
  assert.deepEqual(totals, { subtotal: expected, discount: 0, total: expected });
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
